fn isqrt_floor(n: int) to int {
    if n < 0 {
        return -1
    }
    if n < 2 {
        return n
    }
    let mut lo: int = 1
    let mut hi: int = n / 2 + 1
    let mut ans: int = 1
    while lo <= hi {
        let mid: int = lo + (hi - lo) / 2
        if mid <= n / mid {
            ans = mid
            lo = mid + 1
        } else {
            hi = mid - 1
        }
    }
    return ans
}

fn min_cost_climb(cost: list[int]) to int {
    let n: int = cost.len()
    if n == 0 {
        return 0
    }
    if n == 1 {
        return cost[0].unwrap()
    }
    let mut prev2: int = 0
    let mut prev1: int = 0
    let mut i: int = 2
    while i <= n {
        let c1: int = prev1 + cost[i - 1].unwrap()
        let c2: int = prev2 + cost[i - 2].unwrap()
        let mut best: int = c1
        if c2 < best {
            best = c2
        }
        prev2 = prev1
        prev1 = best
        i = i + 1
    }
    return prev1
}

fn coin_change_min(coins: list[int], amount: int) to int {
    if amount < 0 {
        return -1
    }
    if amount == 0 {
        return 0
    }
    let inf: int = amount + 1
    let mut dp: list[int] = [0]
    let mut a: int = 1
    while a <= amount {
        dp = dp.push(inf)
        a = a + 1
    }
    a = 1
    while a <= amount {
        let mut best: int = inf
        for c in coins {
            if c > 0 and c <= a {
                let cand: int = dp[a - c].unwrap() + 1
                if cand < best {
                    best = cand
                }
            }
        }
        dp[a] = best
        a = a + 1
    }
    let ans: int = dp[amount].unwrap()
    if ans >= inf {
        return -1
    }
    return ans
}

fn knapsack_01(weights: list[int], values: list[int], cap: int) to int {
    if cap <= 0 {
        return 0
    }
    let mut dp: list[int] = []
    let mut w: int = 0
    while w <= cap { dp = dp.push(0)
 w = w + 1 }
    let mut i: int = 0
    while i < weights.len() {
        let wt: int = weights[i].unwrap()
        let val: int = values[i].unwrap()
        let mut c: int = cap
        while c >= wt {
            let cand: int = dp[c - wt].unwrap() + val
            if cand > dp[c].unwrap() {
                dp[c] = cand
            }
            c = c - 1
        }
        i = i + 1
    }
    return dp[cap].unwrap()
}

