fn eval_rpn(tokens: list[str]) to int {
    let mut st: list[int] = []
    for tok in tokens {
        if tok == "+" or tok == "-" or tok == "*" or tok == "/" {
            let b: int = st[st.len() - 1].unwrap()
            st = st.remove_at(st.len() - 1)
            let a: int = st[st.len() - 1].unwrap()
            st = st.remove_at(st.len() - 1)
            let mut v: int = 0
            if tok == "+" { v = a + b } else if tok == "-" { v = a - b } else if tok == "*" { v = a * b } else { v = a / b }
            st = st.push(v)
        } else {
            match tok.to_int() {
                Some(n) => { st = st.push(n) }
                None => {}
            }
        }
    }
    if st.len() == 0 { return 0 }
    return st[0].unwrap()
}

