fn sliding_window_max(nums: list[int], k: int) to list[int] {
    let mut out: list[int] = []
    if k <= 0 or k > nums.len() {
        return out
    }
    let mut i: int = 0
    while i + k <= nums.len() {
        let mut best: int = nums[i].unwrap()
        let mut j: int = i + 1
        while j < i + k {
            if nums[j].unwrap() > best {
                best = nums[j].unwrap()
            }
            j = j + 1
        }
        out = out.push(best)
        i = i + 1
    }
    return out
}

