fn count_components(n: int, edges: list[list[int]]) to int {
    let mut parent: list[int] = []
    let mut i: int = 0
    while i < n { parent = parent.push(i)
 i = i + 1 }
    for e in edges {
        let mut u: int = e[0].unwrap()
        let mut v: int = e[1].unwrap()
        while parent[u].unwrap() != u { u = parent[u].unwrap() }
        while parent[v].unwrap() != v { v = parent[v].unwrap() }
        if u != v {
            parent[v] = u
        }
    }
    let mut roots: int = 0
    i = 0
    while i < n {
        if parent[i].unwrap() == i {
            roots = roots + 1
        }
        i = i + 1
    }
    return roots
}

fn range_sum_queries(nums: list[int], queries: list[list[int]]) to list[int] {
    let mut pref: list[int] = [0]
    let mut acc: int = 0
    for x in nums {
        acc = acc + x
        pref = pref.push(acc)
    }
    let mut out: list[int] = []
    for q in queries {
        let l: int = q[0].unwrap()
        let r: int = q[1].unwrap()
        out = out.push(pref[r + 1].unwrap() - pref[l].unwrap())
    }
    return out
}

