fn eval_infix_arith(expr: str) to int {
    let chars: list[str] = expr.chars()
    let mut st: list[int] = []
    let mut cur: int = 0
    let mut op: str = "+"
    let mut i: int = 0
    while i < chars.len() {
        let ch: str = chars[i].unwrap()
        if ch.is_digit() {
            cur = cur * 10 + (ch.ord() - 48)
        }
        let is_end: bool = i == chars.len() - 1
        if (not ch.is_digit() and ch != " ") or is_end {
            if op == "+" {
                st = st.push(cur)
            } else if op == "-" {
                st = st.push(0 - cur)
            } else if op == "*" {
                let top: int = st[st.len() - 1].unwrap()
                st[st.len() - 1] = top * cur
            }
            if ch == "+" or ch == "-" or ch == "*" {
                op = ch
            }
            cur = 0
        }
        i = i + 1
    }
    let mut total: int = 0
    for v in st { total = total + v }
    return total
}

