fn count_accepted_requests(capacity: int, refill_rate: int, req_times: list[int]) to int {
    if req_times.len() == 0 or capacity <= 0 { return 0 }
    let mut tokens: int = capacity
    let mut prev_t: int = req_times[0].unwrap()
    let mut accepted: int = 0
    for t in req_times {
        let dt: int = t - prev_t
        if dt > 0 {
            tokens = tokens + dt * refill_rate
            if tokens > capacity { tokens = capacity }
            prev_t = t
        }
        if tokens >= 1 {
            tokens = tokens - 1
            accepted = accepted + 1
        }
    }
    return accepted
}

